/**
 * Public endpoint (no auth). The mappingId is a high-entropy random value and the signature is an HMAC embedded as a path segment (not a query param) so relative assets resolve under the signed prefix. The signature is verified server-side via HMAC. The frozen, validated site captured at publish time is served verbatim from the shared preview store — the editable website source is never re-read or re-generated here. Returns 404 no-store if unavailable, expired, or tampered. No signature appears in logs.
 * @summary Serve a signed public prospect preview index page
 */
export const GetProspectPreviewAssetParams = zod.object({
  "mappingId": zod.coerce.string(),
  "signature": zod.coerce.string()
})

